    afterword: '려원은 뿌리력 222년 벨로 해안길에서 고열과 의식 변화를 겪은 열사병으로 일흔하나에 생을 마쳤습니다. 주민들이 그늘과 물을 마련하고 서온도 왔지만 늦었습니다. 서온은 젊은 날 려원을 대신해 한 철 더 밧줄을 살펴야 했던 일을 잊지 않았습니다. 한솔은 려원에게 다시 배나무 열매 하나를 건넸던 일과 이후에도 다른 조에서 일한 세월을 함께 기억했습니다. 전생록은 묘목섬을 구한 순간만 남기지 않습니다. 려원이 자기 실수를 인정하고 손해를 갚았던 시간, 해안에서 어린 나무를 길렀던 노년, 평범한 식사 뒤 찾아온 삶의 끝을 함께 적습니다.',
