      '문턱을 넘기 전에 무릎이 꺾인다. 코조는 손으로 바닥을 밀어 몸을 세우려 하지만 손에도 힘이 빠진다. 옆집 사람이 “누구세요?” 하고 묻는다. 코조는 입을 열지만 대답이 나오지 않는다. 이웃의 발소리가 가까워질 때 시야가 흐려진다. 숨을 한 번 더 들이마시려 했으나 가슴이 움직이지 않는다. 이웃이 문에 도착했을 때 코조는 움직이지 않는다.',
