    afterword: '코조는 1993년 아크라의 집에서 강도의 흉기에 찔린 뒤 출혈로 생을 마쳤습니다. 이웃은 코조의 도움 요청을 듣고 왔지만 강도가 달아난 뒤였습니다. 아바는 전날 오빠와 정한 저녁 약속을 기억했습니다. 아두는 코조가 단골을 넘겨주면서도 자신이 고친 구두를 끝까지 살펴보던 일을 떠올렸습니다. 강도가 잡혔다는 기록은 남기지 않습니다. 전생록은 한 경기의 실수만으로 코조를 설명하지 않습니다. 아버지의 수선대를 지키고, 아두가 독립하도록 도왔으며, 아바 가족과 밥을 나누던 세월과 예고 없이 끊긴 저녁을 함께 적습니다.',
    artUri: 'asset://stories/v3/open-goal-left-final-moment.jpg',
