      '메이는 준의 집 문을 향해 고개를 돌리려 한다. 어느 쪽이 문이었는지 보이지 않는다. 팔을 다시 들어 보지만 움직임이 작아진다. 멀리서 차가 지나가는 소리가 났다가 끊긴다. 누가 올 때까지 눈을 뜨고 있으려 하지만 더는 버틸 수 없다. 골목에는 메이의 이름을 부르는 사람이 없다. 숨이 점차 약해지고, 메이는 그곳에서 생을 마친다.',
