      '여담은 창밖 소리를 듣고 몸을 조금 돌린다. 아래 골목에서 손님들이 물건값을 묻는다. “오늘도 장이야?” 여담이 묻는다. 보리는 열린 창을 보며 “응. 저녁 장이 거의 끝났어”라고 답한다. 여담은 고개를 끄덕이고 입술을 축인다. 보리가 물잔을 가까이 가져오지만, 여담이 고개를 젓자 다시 내려놓는다. 보리는 입가만 젖은 천으로 닦아 준다.',
