    afterword: '여담은 장날력 346년 늦가을, 치매가 진행되며 삼키는 힘이 약해진 뒤 폐렴을 앓다가 나셀의 집에서 일흔여섯에 죽었습니다. 보리는 곁에 있었습니다. 다음 날 가게 문을 늦게 연 보리는 장부와 여담의 돌봄을 함께 맡던 지난 몇 해를 기억했습니다. 소미는 문상을 왔지만 오래전 빵값을 잃었던 일을 없던 일로 말하지 않았습니다. 다해도 나중에 소식을 들었습니다. 여담의 마지막 저녁에 금빛 종이는 없었습니다. 전생록은 누군가를 웃기던 말솜씨와 타인에게 남긴 손해, 보리에게 맡긴 가게와 돌봄을 받던 시간까지 함께 남기며 이 삶을 끝맺습니다.',
