    afterword: '도윤은 화랑력 301년 초가을 루미 구도심에서 떨어진 가게 간판에 머리를 맞고 일흔아홉에 죽었습니다. 과일 장수는 도윤이 피하려고 손을 든 것을 보았지만 그를 길 밖으로 데려갈 시간은 없었습니다. 제자 하리는 공방에서 그림보다 먼저 의뢰인의 말을 듣던 스승을 기억했습니다. 동생 건우는 아버지를 돌보느라 혼자 지낸 밤과 뒤늦게 비용을 나눠 낸 일을 따로 떠올렸습니다. 두 형제는 그 거리를 좁히지 못했습니다. 전생록에는 남의 기억을 함부로 한 얼굴로 합치지 않았던 도윤과, 자기 가족의 시간을 돈으로 다 갚지 못했던 도윤이 함께 남습니다. 과일을 사서 돌아가던 낮에 그의 삶이 끝났습니다.',
