      '화덕력 174년 늦여름 오후, 예순여섯 단우는 동생과 솔마루 위 풀 언덕을 걷는다. 두 사람은 각자의 가게를 쉬는 날에만 이렇게 멀리 나온다. 동생은 장터에서 말린 꽃과 약초를 팔고, 단우는 여전히 공동 빵집의 화덕을 살핀다. 둘은 바위 옆에 앉아 가져온 물을 마신다. 동생이 “오늘은 가게 얘기 말자” 하자 단우가 고개를 끄덕인다.',
      '멀리 골짜기 너머에서 천둥이 난다. 볕이 가려지고 풀이 한쪽으로 눕는다. 둘은 마을로 내려가는 길의 낮은 바위 쉼터를 향해 걷는다. 동생이 먼저 바위 아래에 닿아 돌아본다. 단우는 몇 걸음 뒤 언덕의 드러난 부분을 지나고 있다. “서둘러.” 동생이 부른다. 단우는 걸음을 빠르게 옮기지만 젖기 시작한 돌 사이에 발을 조심해서 딛는다.',
