      '승객칸은 정거장 바깥쪽 선로를 따라 움직인다. 창 너머로 라모의 줄무늬 구름이 보인다. 미라는 손잡이를 잡고 나엘에게 가져갈 작은 과자 봉투를 무릎에 놓는다. 안쪽 거주 구역이 가까워졌을 때 바닥에서 짧은 쇳소리가 난다. 승객칸 앞의 선로 이음부가 벌어지고 경고등이 켜진다. 미라는 과자 봉투를 놓고 두 손으로 손잡이를 쥔다.',
