    afterword: '로아는 바람력 234년 늦여름, 칼렌 고원에서 첫 스승의 집을 다녀오다 심한 더위에 몸을 가누지 못하고 예순여섯에 숨졌습니다. 저녁에 돌아오지 않자 스승과 이웃이 길을 따라 찾았고, 바위 그늘에서 로아를 발견했습니다. 스승은 점심을 함께 먹은 일과, 외딴집의 밤등을 먼저 끄자던 로아의 판단에 끝내 동의하지 못한 일을 모두 기억했습니다. 중심 마을 이웃은 로아 덕에 켠 등불을 말했습니다. 남쪽으로 떠난 가족은 설비값을 돌려받지 못했다고 했습니다. 전생록은 그 손익을 하나로 합치지 않습니다. 로아가 태어나고 오래 일한 고원에서, 스승과 밥을 먹고 돌아오던 날 그의 삶은 끝났습니다.',
