      '숲력 169년 초가을 새벽, 예순다섯 서후는 유리숲 동쪽 강가 집에서 잠을 깬다. 사흘째 열이 있고 기침도 멈추지 않았다. 여울은 밤새 곁방에서 그의 기침을 들었다. 서후는 낮은 침상에서 몸을 일으켜 창을 연다. 강 위로 안개가 낮게 깔려 있다. 찬 공기를 들이마시지만 가슴 안쪽까지 들어오는 느낌이 들지 않는다.',
