      '축제력 121년 이른봄 오후, 예순넷 가온은 골짜기 아래 작은 온천을 나선다. 손이 따뜻해질 때까지 물에 담갔다가 나온 참이다. 온천지기가 “길이 질어요. 천천히 가세요” 하고 말한다. 가온은 고개를 끄덕이고 혼자 마을 쪽 돌길을 오른다. 큰 불꽃을 그만둔 뒤에는 일 없는 날 이곳에 와서 한동안 쉬곤 했다.',
