      '도겸은 허벅지의 찢어진 곳을 손으로 누른다. 손가락 사이로 피가 새고 바지에 번진다. 빨래터의 이웃이 “도겸 씨!” 하고 부르며 다가온다. 이웃은 자기 겉옷을 벗어 접고 상처 위에 단단히 누른다. 도겸은 앉아 있으려 하지만 눈앞의 길이 흐려진다. “계속 눌러요.” 이웃이 말한다. 도겸은 대답 대신 고개만 움직인다.',
