      '성력 245년 늦가을 저녁, 예순넷의 나는 석류성 시장 뒤편 공동 안뜰에서 집에 쓸 물을 긷는다. 시장 동료와 가판을 닫고 돌아온 뒤다. 어머니는 같은 성의 다른 집에서 산다. 오늘도 시장에서 마주쳤지만 함께 집에 오지는 않았다. 건너편 문에서 이웃이 빨래를 거두며 묻는다. “두레박이 또 무거워요?” “오늘은 괜찮아요.”',
