    afterword: '기수는 2002년 가을 서울 집에서 대장암을 앓다가 일흔두 살에 숨을 거뒀습니다. 정희와 딸 은영이 곁에 있었고, 아들 승호는 소식을 듣고 왔습니다. 은영은 문을 열어 둔 채 아버지와 이야기하던 마지막 저녁을 기억했습니다. 정희에게는 함께 두 아이를 키우고 늦게 국을 먹던 날들도, 기수가 바둑 모임 때문에 가게를 일찍 닫아 자기가 돈을 돌려줘야 했던 날도 남았습니다. 승호는 자기 일을 선택할 때 아버지가 걱정하면서도 막지 않았던 일을 떠올렸습니다. 전생록은 그들이 서로 다르게 기억하는 기수의 삶이 그날 저녁 끝났다고 전합니다.',
