    afterword: '토치틀은 1510년 소치밀코 집에서 무너진 지붕 들보에 가슴을 맞고 쉰여덟 살에 숨을 거뒀습니다. 이츠엘과 성인 딸 아마가 곁에 있었지만 그를 살리지 못했습니다. 사고가 왜 그날 일어났는지는 알 수 없습니다. 남동생 틀랄리는 소식을 듣고 왔습니다. 그는 전날까지도 형과 물길 차례를 두고 다퉜고, 형이 자기 일을 늦게 이해하던 날도 기억했습니다. 아마는 아버지에게 배운 농사법을 쓰면서도 자기 살림은 스스로 정했습니다. 이츠엘은 토치틀이 집에서는 밭에서만큼 빨리 생각을 바꾸지 않았다고 말했습니다. 전생록은 한 번의 밭 나누기와 갑작스러운 끝 사이에 있던 가족의 시간과 남은 다툼을 함께 적으며 이 삶을 끝맺습니다.',
