      '1935년 흐린 오후, 나는 비냐델마르에 따로 얻은 방의 의자에 앉아 있다. 몇 주째 식욕이 없고 계단을 오르면 숨이 차다. 누나 필라르가 국 한 그릇을 가져왔다. 누나는 내 앞에 그릇을 놓고 “조금이라도 먹어”라고 말한다. 나는 숟가락을 들었다가 내려놓는다. 지금은 냄새만 맡아도 속이 답답하다.',
