      '기록소의 매일 일을 그만둔 지 네 해가 지났다. 오늘은 젊은 기록자가 오래된 이름 하나를 물으러 와 달라고 해서, 작은 밭을 돌본 뒤 성 밖 기록소에 잠시 들렀다. 창을 열자 비 그친 성벽이 보인다. 나는 오래된 장부에 적힌 이름 하나를 새 장부에서 찾는다. 글씨가 옅어져 두루마리 누름돌로 종이를 눌러 놓고 고개를 숙인다. 예전에는 빠진 줄을 금방 찾아냈는데, 오늘은 같은 자리를 세 번 읽어도 눈앞의 글자가 겹쳐 보인다.',
      '“제가 읽을게요.” 젊은 기록자가 내 옆에 선다. 그 애는 이름을 소리 내어 읽고 곁에 적힌 옛 주소까지 짚는다. “그 집은 옮겨 갔어. 뒤쪽 장부도 봐.” 내가 말하자 그 애는 서둘러 새 줄을 쓰지 않고 원본을 가져온다. 두 책 사이에 끼워 둔 얇은 쪽지에는 유진의 글씨가 있다. 쉬는 날 성벽을 걷자던 짧은 약속이다.',
