      '유진이 문가에서 젖은 신을 벗는다. “비가 그쳤어. 조금만 걸을래?” 나는 일어나려다 다시 의자에 기대고 웃는다. “다음에.” 그 애가 의자를 끌어와 내 곁에 앉는다. 창밖의 물방울이 처마 끝에서 하나씩 떨어지고, 젊은 기록자는 책장을 조용히 넘긴다. 나는 누름돌 아래의 종이가 바람에 들리지 않는 것을 본다. 유진에게 아직 묻지 못한 길 이야기를 생각하며 눈을 감는다.',
