    afterword: '왕력 368년, 세아는 안개성에서 삶을 마쳤습니다. 유진은 비가 그친 성벽을 혼자 걸은 뒤, 두 사람이 걷기로 했던 날의 쪽지를 기록소 책갈피에 남겼습니다. 젊은 기록자는 세아가 찾던 이름을 원본과 대조해 적고, 닳은 누름돌을 다음 사람의 책상에 놓았습니다. 그렇게 또 하나의 삶이 끝났습니다. 전생록은 그 작은 방에서 이어진 이름들을 이 장에 두고, 또 다른 삶의 첫 장을 기다립니다.',
