const replacementFinalMomentById = new Map(
  replacementFinalMoments20c.map((moment) => [moment.storyId, moment]),
);

export const storyFinalMoments: readonly StoryFinalMoment[] = originalStoryFinalMoments.map(
  (moment) => replacementFinalMomentById.get(moment.storyId) ?? moment,
);

export function findStoryFinalMoment(storyId: string): StoryFinalMoment | undefined {
  return storyFinalMoments.find((moment) => moment.storyId === storyId);
}
